mapper.update:
update builder.adk_builder_user_manual
   set html = #{html}, created_at = now(), generation_state = 'DONE', failed_reason = null,
       source_fingerprint = #{sourceFingerprint}, generator_version = #{generatorVersion},


       capture_bundle_path = #{capture.bundlePath},
       capture_file_name = #{capture.fileName},
       capture_label = #{capture.label},
       capture_width = #{capture.width},
       capture_height = #{capture.height},
       capture_sha256 = #{capture.sha256}


       capture_bundle_path = null, capture_file_name = null, capture_label = null,
       capture_width = null, capture_height = null, capture_sha256 = null


 where project_id = #{projectId}
   and system_code = #{systemCode}
   and screen_id = #{screenId}
   and generation_id = #{generationId}
   and generation_state = 'RUNNING'

update builder.adk_builder_user_manual
   set generation_state = 'FAILED', failed_reason = #{reason}
 where project_id = #{projectId}
   and system_code = #{systemCode}
   and screen_id = #{screenId}
   and generation_id = #{generationId}
   and generation_state = 'RUNNING'

mapper.select:
select 
  from builder.adk_builder_user_manual
 where project_id = #{projectId}
   and system_code = #{systemCode}
   and screen_id = #{screenId}

select capture_bundle_path as bundlePath, capture_file_name as fileName,
       capture_label as label, capture_width as width, capture_height as height,
       capture_sha256 as sha256
  from builder.adk_builder_user_manual
 where project_id = #{projectId}
   and system_code = #{systemCode}
   and screen_id = #{screenId}
   and capture_bundle_path is not null

select 
  from builder.adk_builder_user_manual
 where project_id = #{projectId}
   and system_code = #{systemCode}
   and screen_id = #{screenId}
